use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < 'a > MemDecoder < 'a > { # [inline] pub fn new (data : & 'a [u8] , position : usize) -> Result < MemDecoder < 'a > , () > { let data = data . strip_suffix (MAGIC_END_BYTES) . ok_or (()) ? ; let Range { start , end } = data . as_ptr_range () ; Ok (MemDecoder { start , current : data [position ..] . as_ptr () , end , _marker : PhantomData }) } # [inline] pub fn split_at (& self , position : usize) -> MemDecoder < 'a > { assert ! (position <= self . len ()) ; let current = unsafe { self . start . add (position) } ; MemDecoder { start : self . start , current , end : self . end , _marker : PhantomData } } # [inline] pub fn len (& self) -> usize { unsafe { self . end . offset_from_unsigned (self . start) } } # [inline] pub fn remaining (& self) -> usize { unsafe { self . end . offset_from_unsigned (self . current) } } # [cold] # [inline (never)] fn decoder_exhausted () -> ! { panic ! ("MemDecoder exhausted") } # [inline] pub fn read_array < const N : usize > (& mut self) -> [u8 ; N] { self . read_raw_bytes (N) . try_into () . unwrap () } # [doc = " While we could manually expose manipulation of the decoder position,"] # [doc = " all current users of that method would need to reset the position later,"] # [doc = " incurring the bounds check of set_position twice."] # [inline] pub fn with_position < F , T > (& mut self , pos : usize , func : F) -> T where F : Fn (& mut MemDecoder < 'a >) -> T , { struct SetOnDrop < 'a , 'guarded > { decoder : & 'guarded mut MemDecoder < 'a > , current : * const u8 , } impl Drop for SetOnDrop < '_ , '_ > { fn drop (& mut self) { self . decoder . current = self . current ; } } if pos >= self . len () { Self :: decoder_exhausted () ; } let previous = self . current ; unsafe { self . current = self . start . add (pos) ; } let guard = SetOnDrop { current : previous , decoder : self } ; func (guard . decoder) } }
}